// Generated by vibelang from worker/Placement.ts; the migrate flow writes it again with each batch.
import { Config, Option, Schema } from "effect";
// Where the remote flow executions' Durable Objects live (docs/infrastructure.md#placement). Every engine statement is
// a round trip from an execution's object to Postgres, and the engine's writes hold its schema's one writer lock across
// theirs, so the round trip sets how many writes the whole deployment makes a second. Cloudflare creates an object near
// its first caller unless told otherwise; measured on 2026-10-22 behind the production Hyperdrive config, an object
// near San Jose took 80 ms a round trip to Neon in us-east-1, and one hinted `enam` 4 ms.
/** Cloudflare's Durable Object location hints. */
export const LocationHint = Schema.Literals(["wnam", "enam", "sam", "weur", "eeur", "apac", "oc", "afr", "me"]);
/**
 * `FLOW_EXECUTION_LOCATION`: the location hint a new execution's Durable Object is created with, such as `enam` for a
 * database in us-east-1; unset, Cloudflare creates it near its first caller. A deployment value: the public stack
 * leaves it unset.
 */
export const location = Config.option(Config.schema(LocationHint, "FLOW_EXECUTION_LOCATION"));
/**
 * `namespace`, whose objects are created at `hint` when it is set. A hint matters only when an object is created, so
 * every caller that may create one, the starter and each router alike, reaches it through this.
 */
export const placed = (namespace, hint) => ({
    getByName: (name) => Option.isSome(hint) ? namespace.getByName(name, { locationHint: hint.value }) : namespace.getByName(name),
});
